export function createOptimisticStore(initialState) {
  let base = initialState;
  let pending = [];
  const listeners = [];

  const getState = () => {
    if (pending.length === 0) return base;
    return pending.reduce((s, m) => m.update(s), base);
  };

  const apply = (id, update) => {
    if (pending.some(m => m.id === id)) throw new Error("Change already pending");
    try {
      const newState = update(getState());
      pending.push({ id, update });
      notifyListeners();
    } catch (error) {
      throw error;
    }
  };

  const confirm = (id) => {
    const index = pending.findIndex(m => m.id === id);
    if (index === -1) return false;
    base = pending[index].update(base);
    pending = pending.filter((_, i) => i !== index);
    notifyListeners();
    return true;
  };

  const rollback = (id) => {
    const index = pending.findIndex(m => m.id === id);
    if (index === -1) return false;
    pending = pending.filter((_, i) => i !== index);
    notifyListeners();
    return true;
  };

  const subscribe = (listener) => {
    listeners.push(listener);
    return () => {
      const index = listeners.indexOf(listener);
      if (index !== -1) listeners.splice(index, 1);
    };
  };

  const notifyListeners = () => {
    listeners.forEach(listener => {
      try {
        listener();
      } catch (error) {
        // Swallow errors in listeners
      }
    });
  };

  return {
    getState,
    apply,
    confirm,
    rollback,
    subscribe
  };
}
